# «ماذا تفعل؟» — الدراسات الاجتماعية (الصفوف 1–4). الصواب مأخوذ من «تعلّمتُ» (learn) أو فكرة الدرس نفسه،
# والشاهد عند الإدخال: فكرة الدرس منسوبةً إليه.
S = {'SS-Y1-T1-L05': [('جارك الكبير في السن مريض منذ أيام.', [('أسلّم عليه مع أسرتي وأسأل عن صحته.', 1, 'أحسنت! نسأل عن صحة جارنا.'), ('لا أهتم، فهو ليس من أسرتي.', 0, 'الجار قبل الدار.'), ('ألعب بصوت عالٍ أمام بيته.', 0, 'الإزعاج يؤذي جارنا المريض.')])], 'SS-Y1-T1-L06': [('رُزقت أسرة جارك بمولود جديد.', [('أهنئ جاري بالمولود الجديد.', 1, 'أحسنت! نهنئ جيراننا في أفراحهم.'), ('لا أقول شيئًا.', 0, 'التهنئة تفرح الجار.'), ('أشتكي من بكاء الطفل أمامهم.', 0, 'لا نسيء إلى جيراننا.')])], 'SS-Y1-T1-L04': [('في العيد دعتك أسرتك لزيارة عمك وخالك.', [('أذهب معهم فرحًا وأساعد أقاربي.', 1, 'أحسنت! نزور أقاربنا في المناسبات ونساعدهم.'), ('أبقى في البيت ألعب بالهاتف.', 0, 'زيارة الأقارب تقوّي المحبة.'), ('أذهب وأتذمّر طوال الوقت.', 0, 'نزور أقاربنا بفرح.')])], 'SS-Y1-T3-L01': [('أردت الذهاب إلى بيت صديقك في الحي.', [('أستأذن والديّ قبل أن أخرج.', 1, 'أحسنت! لا أخرج دون إذن والديّ.'), ('أخرج بسرعة قبل أن يروني.', 0, 'الخروج دون إذن يقلق الأسرة.'), ('أخرج وأخبرهم بعد أن أعود.', 0, 'الإذن يكون قبل الخروج.')])], 'SS-Y1-T3-L02': [('دخلت مكتبة المدرسة مع صديقك، وهو يريد أن يحكي لك قصة مضحكة.', [('ألتزم الهدوء، ونتحدث بعد أن نخرج.', 1, 'أحسنت! نلتزم الهدوء في المكتبة.'), ('نضحك بصوت عالٍ.', 0, 'الضجيج يزعج من يقرأ.'), ('نركض بين الرفوف.', 0, 'للمكتبة نظام نحترمه.')])], 'SS-Y1-T3-L03': [('انتهيت من اللعب في حديقة الحي، ومعك علبة عصير فارغة.', [('أضعها في سلة النفايات.', 1, 'أحسنت! نظافة مدينتي مسؤوليتي.'), ('أتركها على العشب.', 0, 'الممتلكات العامة ملك للجميع.'), ('أرميها خلف الشجرة.', 0, 'الحديقة تبقى نظيفة بنا.')])], 'SS-Y1-T3-L06': [('في بيتك علب بلاستيكية وأوراق كثيرة فارغة.', [('أضعها في حاوية إعادة التدوير.', 1, 'أحسنت! الورق والبلاستيك يُعاد تدويرهما.'), ('أرميها مع بقايا الطعام.', 0, 'نضع النفايات في الحاويات المخصصة.'), ('أحرقها في الفناء.', 0, 'الحرق يلوّث الهواء.')])], 'SS-Y1-T3-L05': [('ذهبت مع أسرتك إلى الشاطئ، وانتهيتم من الطعام.', [('نجمع المخلفات ونضعها في الحاوية.', 1, 'أحسنت! ممنوع رمي المخلفات على الشواطئ.'), ('نتركها، فالموج سيأخذها.', 0, 'المخلفات تلوّث البحر.'), ('ندفنها في الرمل.', 0, 'هذا يضر الشاطئ والكائنات.')])], 'SS-Y2-T2-L03': [('تغسل يديك، والماء يجري بقوة.', [('أغلق الصنبور وأنا أفرك يدي بالصابون.', 1, 'أحسنت! ترشيد الاستهلاك أفضل حل لنقص المياه.'), ('أتركه مفتوحًا حتى أنتهي.', 0, 'الإسراف من أسباب نقص المياه.'), ('أفتحه أكثر لأنتهي بسرعة.', 0, 'هذا يهدر الماء.')])], 'SS-Y2-T2-L05': [('أبوك يريد شراء مصباح جديد للبيت.', [('أقترح المصباح الموفّر للطاقة.', 1, 'أحسنت! نوفّر الطاقة ونحمي البيئة.'), ('أقول: نشتري أي مصباح، لا فرق.', 0, 'المصباح الموفّر يقلل استهلاك الكهرباء.'), ('أقترح أن نترك الأضواء مضاءة دائمًا.', 0, 'هذا هدر للطاقة.')])], 'SS-Y2-T2-L16': [('صديقتك تعرض عليك أن تنقل واجبها لأنك نسيت حلّ واجبك.', [('أشكرها وأحل واجبي بنفسي.', 1, 'أحسنت! الأمانة ألا آخذ جهد غيري.'), ('أنقله وأكتب اسمي عليه.', 0, 'هذا نسبة جهد غيري لنفسي.'), ('أنقل نصفه فقط.', 0, 'الأمانة لا تتجزأ.')])], 'SS-Y2-T2-L17': [('سألتك أمك: من أكل الحلوى كلها؟ وأنت أكلتها.', [('أعترف بالحقيقة وأعتذر.', 1, 'أحسنت! الاعتراف بالخطأ شجاعة.'), ('أقول: أختي أكلتها.', 0, 'الكذب صفة سيئة.'), ('أقول: لا أعرف.', 0, 'الصدق قول الحقيقة.')])], 'SS-Y2-T2-L18': [('فريقك في الصف يصنع مجسمًا كبيرًا، والوقت قصير.', [('أقوم بدوري وأساعد زملائي.', 1, 'أحسنت! بالتعاون نحقق الهدف.'), ('أتركهم يعملون وأتفرج.', 0, 'لكل فرد دور في العمل.'), ('أعمل وحدي وأرفض مساعدتهم.', 0, 'التعاون أن نعمل معًا.')])], 'SS-Y2-T3-L06': [('في البوفيه أطعمة كثيرة تحبها.', [('أضع في طبقي قدر حاجتي.', 1, 'أحسنت! الترشيد استهلاك معتدل بلا إسراف.'), ('أملأ طبقي كثيرًا ثم أترك نصفه.', 0, 'هذا هدر للطعام والمال.'), ('آخذ ثلاثة أطباق مرة واحدة.', 0, 'نأخذ قدر حاجتنا.')])], 'SS-Y2-T3-L05': [('رأيت لعبة جديدة في المتجر، ولديك ألعاب كثيرة تشبهها.', [('أسأل نفسي: هل أحتاجها فعلًا؟ ثم أقرر.', 1, 'أحسنت! «مدّ ريولك على قدّ لحافك».'), ('أشتريها فورًا لأنها جديدة.', 0, 'شراء ما لا نحتاجه هدر للمال.'), ('أبكي حتى يشتريها والداي.', 0, 'نحترم قرار الأسرة في الإنفاق.')])], 'SS-Y3-T1-L05': [('مدرستك قريبة، ووالدك يعرض أن يوصلك وحدك بالسيارة كل يوم، وهناك حافلة مدرسية.', [('أركب الحافلة المدرسية مع زملائي.', 1, 'أحسنت! النقل الجماعي يحمي البيئة.'), ('أطلب سيارة خاصة كل يوم.', 0, 'سيارات أكثر تعني تلوثًا أكثر.'), ('أطلب أن يبقى محرك السيارة يعمل وأنا أنتظر.', 0, 'هذا هدر للطاقة وتلويث للهواء.')])], 'SS-Y3-T1-L06': [('انتهيت من مرطبان زجاجي فارغ في المطبخ.', [('أعيد استخدامه لحفظ الأقلام أو لزراعة نبتة.', 1, 'أحسنت! أعيد استخدام الأشياء.'), ('أرميه في سلة النفايات فورًا.', 0, 'يمكن أن يُستخدم مرة أخرى.'), ('أكسره لأتخلص منه.', 0, 'هذا هدر وخطر.')])], 'SS-Y3-T2-L10': [('استيقظت متأخرًا، وغرفتك غير مرتّبة.', [('أرتّب سريري وغرفتي بنفسي.', 1, 'أحسنت! هذا من واجباتي.'), ('أتركها لأمي.', 0, 'أعتمد على نفسي في واجباتي.'), ('أغلق الباب حتى لا يراها أحد.', 0, 'الإخفاء لا يرتّب الغرفة.')])], 'SS-Y3-T2-L11': [('اختلفت مع أخيك على من يجلس قرب النافذة.', [('أحل الخلاف بالحوار، ونتبادل المكان.', 1, 'أحسنت! نحل الخلاف بالحوار.'), ('أدفعه وأجلس مكانه.', 0, 'القوة لا تحل الخلاف.'), ('أصرخ حتى يتركه لي.', 0, 'الاحترام بين الإخوة واجب.')])], 'SS-Y3-T2-L14': [('انتهيت من نزهة مع جيرانك في حديقة الحي، وبقيت أكياس وعلب.', [('أجمعها وأضع المخلفات في مكانها.', 1, 'أحسنت! نحافظ على الحديقة لأنها للجميع.'), ('أتركها لعامل النظافة.', 0, 'أضع المخلفات في مكانها بنفسي.'), ('أخبّئها تحت المقعد.', 0, 'هذا يلوّث الحديقة.')])], 'SS-Y3-T2-L12': [('رأيت كتابات على جدار موقف الحافلات.', [('لا أشارك في التخريب، وأخبر الجهة المسؤولة.', 1, 'أحسنت! أحافظ على المرافق العامة.'), ('أضيف رسمي أنا أيضًا.', 0, 'هذا تخريب للمرافق العامة.'), ('أقول: ليس من شأني.', 0, 'المرافق العامة مسؤوليتنا جميعًا.')])], 'SS-Y4-T2-L07': [('في رحلة إلى البر، أراد بعض الزملاء ترك أكياس البلاستيك في الصحراء.', [('أجمعها معهم ونضعها في الحاوية.', 1, 'أحسنت! نمنع تلوث الأرض.'), ('أتركها، فالصحراء واسعة.', 0, 'البلاستيك يضر التربة والكائنات.'), ('أحرقها.', 0, 'الحرق يلوث الهواء.')])], 'SS-Y4-T2-L08': [('تذهب أنت وثلاثة من جيرانك إلى المدرسة نفسها كل صباح.', [('نذهب معًا بالحافلة المدرسية.', 1, 'أحسنت! النقل الجماعي من حلول الازدحام المروري.'), ('كل أسرة تذهب بسيارتها.', 0, 'كثرة المركبات تسبب الازدحام.'), ('نخرج متأخرين ونطلب الإسراع.', 0, 'السرعة خطر ولا تحل الازدحام.')])]}
